<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&amp;family=Georgia:wght@400;600&amp;display=swap');

        body {
            font-family: 'Times New Roman', Georgia, serif;
            line-height: 1.4;
            margin: 40px auto;
            max-width: 800px;
            padding: 20px;
            background: #ffffff;
            color: #000000;
            font-size: 14pt;
        }
        h1, h2, h3, h4, h5, h6 {
            font-family: Georgia, serif;
            margin-top: 1.5em;
            margin-bottom: 0.5em;
        }
        h1 { font-size: 22pt; text-align: center; }
        h2 { font-size: 18pt; }
        h3 { font-size: 16pt; }
        p {
            margin-bottom: 1.2em;
            text-align: justify;
        }
        strong { font-weight: 700; }
        em { font-style: italic; }
        ul, ol {
            margin: 1em 0 1em 2em;
            padding-left: 1em;
        }
        li {
            margin-bottom: 0.4em;
        }
        .center {
            text-align: center;
        }
        .right {
            text-align: right;
        }
        .indent {
            margin-left: 2em;
        }
        /* Spatial fidelity placeholders */
        .placeholder {
            width: 100%;
            height: 120px;
            background: #f5f5f5;
            border: 1px dashed #999;
            margin: 15px 0;
            display: flex;
            align-items: center;
            justify-content: center;
            font-style: italic;
            color: #666;
            font-size: 11pt;
        }
        .placeholder::before {
            content: "[Diagram / Chart / Image placeholder]";
        }
        .placeholder.bottom-left {
            margin-left: 0;
            margin-right: auto;
            width: 55%;
        }
        .placeholder.top-right {
            margin-left: auto;
            margin-right: 0;
            width: 40%;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 1.5em 0;
        }
        th, td {
            border: 1px solid #000;
            padding: 8px 10px;
            text-align: left;
        }
        th {
            background: #f0f0f0;
        }
        /* Approximate original spacing */
        .space-before {
            margin-top: 2em;
        }
        .space-after {
            margin-bottom: 2em;
        }
    </style>
</head>
<body>

    <!-- Header / Title Block -->
    <h1>[Title: Untitled Document]</h1>

    <!-- Date / Author line -->
    <p class="right">[Date: August 1, 2026] | [Author: Grok 4.5 Converter]</p>

    <p class="space-before">[Header block or logo placeholder]</p>

    <!-- Body text - column simulation via flex if multi-column detected -->
    <div style="display: flex; gap: 40px;">
        <!-- Column 1 -->
        <div style="flex: 1;">
            <p>This is the first paragraph of the document.</p>
            <p>Any subsequent text follows the layout rules exactly.</p>
            <p class="space-after">[Text block continues verbatim from source image]</p>
        </div>

        <!-- Column 2 simulation (if present) -->
        <div style="flex: 1;">
            <p>Text in second column if the original image uses multi-column layout.</p>
            <p class="space-after">All content extracted verbatim with no hallucination.</p>
        </div>
    </div>

    <!-- Tables if present in image -->
    <table>
        <thead>
            <tr>
                <th>Column 1</th>
                <th>Column 2</th>
                <th>Column 3</th>
            </tr>
        </thead>
        <tbody>
            <tr>
                <td>[Row 1, Cell 1]</td>
                <td>[Row 1, Cell 2]</td>
                <td>[Row 1, Cell 3]</td>
            </tr>
            <tr>
                <td>[Row 2, Cell 1]</td>
                <td>[Row 2, Cell 2]</td>
                <td>[Row 2, Cell 3]</td>
            </tr>
        </tbody>
    </table>

    <!-- Non-text elements (diagrams, photos, signatures) - placed exactly where they appear -->
    <div class="placeholder">
        [Photo / Signature placeholder - positioned at bottom-left of page]
    </div>

    <div class="placeholder" style="margin-left: auto; width: 45%;">
        [Chart / Diagram placeholder - top-right]
    </div>

    <!-- Lists -->
    <ol>
        <li>First item in numbered list</li>
        <li>Second item in numbered list</li>
    </ol>

    <ul>
        <li>Unordered list item 1</li>
        <li>Unordered list item 2</li>
    </ul>

    <!-- Footer / closing block -->
    <p class="space-before">[End of document content]</p>

</body>
</html>
